package org.springframework.samples.petclinic.owner;

import java.time.LocalDate;
import java.util.List;
import java.util.Optional;

import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.condition.DisabledInNativeImage;
import org.mockito.ArgumentCaptor;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.webmvc.test.autoconfigure.WebMvcTest;
import org.springframework.context.annotation.ComponentScan;
import org.springframework.context.annotation.FilterType;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.test.context.aot.DisabledInAotMode;
import org.springframework.test.context.bean.override.mockito.MockitoBean;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.test.web.servlet.MvcResult;
import org.springframework.validation.BindingResult;
import org.springframework.validation.FieldError;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.BDDMockito.given;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.verify;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.flash;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.model;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.view;

/**
 * Characterization tests that pin the current validation and save behavior of
 * {@link PetController} before it is restructured. They describe what the code does
 * today, not necessarily what it should do.
 */
@WebMvcTest(value = PetController.class,
		includeFilters = @ComponentScan.Filter(value = PetTypeFormatter.class, type = FilterType.ASSIGNABLE_TYPE))
@DisabledInNativeImage
@DisabledInAotMode
class PetControllerCharacterizationTests {

	private static final int OWNER_ID = 1;

	private static final int PETTY_ID = 1;

	private static final int DOGGY_ID = 2;

	private static final String FORM = "pets/createOrUpdatePetForm";

	@Autowired
	private MockMvc mockMvc;

	@MockitoBean
	private OwnerRepository owners;

	@MockitoBean
	private PetTypeRepository types;

	private Owner owner;

	private Pet petty;

	private PetType hamster;

	@BeforeEach
	void setup() {
		hamster = new PetType();
		hamster.setId(3);
		hamster.setName("hamster");
		given(this.types.findPetTypes()).willReturn(List.of(hamster));

		owner = new Owner();
		petty = new Pet();
		petty.setId(PETTY_ID);
		petty.setName("petty");
		petty.setBirthDate(LocalDate.of(2010, 1, 1));
		Pet doggy = new Pet();
		doggy.setId(DOGGY_ID);
		doggy.setName("doggy");
		owner.addPet(petty);
		owner.addPet(doggy);
		given(this.owners.findById(OWNER_ID)).willReturn(Optional.of(owner));
	}

	// ---- create form ----

	@Test
	void createSavesOwnerWithNewPetAndFlashesMessage() throws Exception {
		mockMvc
			.perform(post("/owners/{ownerId}/pets/new", OWNER_ID).param("name", "Betty")
				.param("type", "hamster")
				.param("birthDate", "2015-02-12"))
			.andExpect(status().is3xxRedirection())
			.andExpect(view().name("redirect:/owners/{ownerId}"))
			.andExpect(flash().attribute("message", "New Pet has been Added"));

		verify(owners).saveAndFlush(owner);
		Pet betty = owner.getPet("Betty");
		assertThat(betty).isNotNull();
		assertThat(betty.getBirthDate()).isEqualTo(LocalDate.of(2015, 2, 12));
		assertThat(betty.getType()).isSameAs(hamster);
		assertThat(owner.getPets()).hasSize(3);
	}

	@Test
	void createAcceptsBirthDateOfToday() throws Exception {
		mockMvc
			.perform(post("/owners/{ownerId}/pets/new", OWNER_ID).param("name", "Betty")
				.param("type", "hamster")
				.param("birthDate", LocalDate.now().toString()))
			.andExpect(status().is3xxRedirection());
	}

	@Test
	void createRejectsBirthDateOfTomorrowWithCodeOnlyAndDoesNotSave() throws Exception {
		MvcResult result = mockMvc
			.perform(post("/owners/{ownerId}/pets/new", OWNER_ID).param("name", "Betty")
				.param("type", "hamster")
				.param("birthDate", LocalDate.now().plusDays(1).toString()))
			.andExpect(status().isOk())
			.andExpect(view().name(FORM))
			.andExpect(model().errorCount(1))
			.andExpect(model().attributeHasFieldErrorCode("pet", "birthDate", "typeMismatch.birthDate"))
			.andReturn();

		// SUSPECT: a future date is reported with the parse-error code typeMismatch
		// and no default message.
		assertThat(
				result.getModelAndView().getModel().get("org.springframework.validation.BindingResult.pet").toString())
			.contains("default message [null]");
		verify(owners, never()).saveAndFlush(any());
	}

	@Test
	void createMissingBirthDateIsRequired() throws Exception {
		mockMvc.perform(post("/owners/{ownerId}/pets/new", OWNER_ID).param("name", "Betty").param("type", "hamster"))
			.andExpect(status().isOk())
			.andExpect(model().errorCount(1))
			.andExpect(model().attributeHasFieldErrorCode("pet", "birthDate", "required"));
	}

	@Test
	void createDuplicateNameIsCaseInsensitive() throws Exception {
		mockMvc
			.perform(post("/owners/{ownerId}/pets/new", OWNER_ID).param("name", "PETTY")
				.param("type", "hamster")
				.param("birthDate", "2015-02-12"))
			.andExpect(status().isOk())
			.andExpect(model().errorCount(1))
			.andExpect(model().attributeHasFieldErrorCode("pet", "name", "duplicate"));
		verify(owners, never()).saveAndFlush(any());
	}

	@Test
	void createDuplicateCheckIgnoresUnsavedPetsOfOwner() throws Exception {
		Pet unsaved = new Pet();
		unsaved.setName("Ghost");
		owner.getPets().add(unsaved);

		mockMvc
			.perform(post("/owners/{ownerId}/pets/new", OWNER_ID).param("name", "ghost")
				.param("type", "hamster")
				.param("birthDate", "2015-02-12"))
			.andExpect(status().is3xxRedirection());
	}

	@Test
	void createBlankNameReportsOnlyRequiredNotDuplicate() throws Exception {
		mockMvc
			.perform(post("/owners/{ownerId}/pets/new", OWNER_ID).param("name", "")
				.param("type", "hamster")
				.param("birthDate", "2015-02-12"))
			.andExpect(model().errorCount(1))
			.andExpect(model().attributeHasFieldErrorCode("pet", "name", "required"));
	}

	@Test
	void createNameOf30CharsAccepted() throws Exception {
		mockMvc
			.perform(post("/owners/{ownerId}/pets/new", OWNER_ID).param("name", "A".repeat(30))
				.param("type", "hamster")
				.param("birthDate", "2015-02-12"))
			.andExpect(status().is3xxRedirection());
	}

	@Test
	void createNameOf31CharsRejectedWithSize() throws Exception {
		mockMvc
			.perform(post("/owners/{ownerId}/pets/new", OWNER_ID).param("name", "A".repeat(31))
				.param("type", "hamster")
				.param("birthDate", "2015-02-12"))
			.andExpect(status().isOk())
			.andExpect(model().errorCount(1))
			.andExpect(model().attributeHasFieldErrorCode("pet", "name", "size"));
	}

	@Test
	void createReportsDuplicateNameAndFutureBirthDateTogether() throws Exception {
		mockMvc
			.perform(post("/owners/{ownerId}/pets/new", OWNER_ID).param("name", "petty")
				.param("type", "hamster")
				.param("birthDate", LocalDate.now().plusDays(1).toString()))
			.andExpect(status().isOk())
			.andExpect(model().errorCount(2))
			.andExpect(model().attributeHasFieldErrorCode("pet", "name", "duplicate"))
			.andExpect(model().attributeHasFieldErrorCode("pet", "birthDate", "typeMismatch.birthDate"));
	}

	@Test
	void createReportsEveryValidatorErrorAtOnce() throws Exception {
		mockMvc.perform(post("/owners/{ownerId}/pets/new", OWNER_ID).param("name", ""))
			.andExpect(status().isOk())
			.andExpect(model().errorCount(3))
			.andExpect(model().attributeHasFieldErrorCode("pet", "name", "required"))
			.andExpect(model().attributeHasFieldErrorCode("pet", "type", "required"))
			.andExpect(model().attributeHasFieldErrorCode("pet", "birthDate", "required"));
	}

	@Test
	void createUnparseableBirthDateReportsTypeMismatchAndRequired() throws Exception {
		MvcResult result = mockMvc
			.perform(post("/owners/{ownerId}/pets/new", OWNER_ID).param("name", "Betty")
				.param("type", "hamster")
				.param("birthDate", "2015/02/12"))
			.andExpect(status().isOk())
			.andExpect(model().errorCount(2))
			.andExpect(model().attributeHasFieldErrorCode("pet", "birthDate", "typeMismatch"))
			.andReturn();
		BindingResult errors = (BindingResult) result.getModelAndView()
			.getModel()
			.get(BindingResult.MODEL_KEY_PREFIX + "pet");
		assertThat(errors.getFieldErrors("birthDate")).extracting(FieldError::getCode)
			.containsExactly("typeMismatch", "required");
	}

	@Test
	void createIgnoresSubmittedId() throws Exception {
		mockMvc
			.perform(post("/owners/{ownerId}/pets/new", OWNER_ID).param("id", "99")
				.param("name", "Betty")
				.param("type", "hamster")
				.param("birthDate", "2015-02-12"))
			.andExpect(status().is3xxRedirection());
		assertThat(owner.getPet("Betty").getId()).isNull();
	}

	@Test
	void createUniqueViolationMessageMatchedCaseInsensitively() throws Exception {
		given(owners.saveAndFlush(any(Owner.class)))
			.willThrow(new DataIntegrityViolationException("Duplicate key: UNIQUE_OWNER_PET_NAME"));
		mockMvc
			.perform(post("/owners/{ownerId}/pets/new", OWNER_ID).param("name", "Betty")
				.param("type", "hamster")
				.param("birthDate", "2015-02-12"))
			.andExpect(status().isOk())
			.andExpect(view().name(FORM))
			.andExpect(model().attributeHasFieldErrorCode("pet", "name", "duplicate"));
	}

	@Test
	void createOtherIntegrityViolationIsRethrown() {
		given(owners.saveAndFlush(any(Owner.class))).willThrow(new DataIntegrityViolationException("fk_type"));
		assertThatThrownBy(() -> mockMvc.perform(post("/owners/{ownerId}/pets/new", OWNER_ID).param("name", "Betty")
			.param("type", "hamster")
			.param("birthDate", "2015-02-12"))).hasRootCauseInstanceOf(DataIntegrityViolationException.class);
	}

	// ---- edit form ----

	@Test
	void editUpdatesExistingPetAndFlashesMessage() throws Exception {
		mockMvc
			.perform(post("/owners/{ownerId}/pets/{petId}/edit", OWNER_ID, PETTY_ID).param("name", "Betty")
				.param("type", "hamster")
				.param("birthDate", "2015-02-12"))
			.andExpect(status().is3xxRedirection())
			.andExpect(view().name("redirect:/owners/{ownerId}"))
			.andExpect(flash().attribute("message", "Pet details has been edited"));

		verify(owners).saveAndFlush(owner);
		assertThat(owner.getPets()).hasSize(2);
		assertThat(petty.getName()).isEqualTo("Betty");
		assertThat(petty.getBirthDate()).isEqualTo(LocalDate.of(2015, 2, 12));
		assertThat(petty.getType()).isSameAs(hamster);
		assertThat(petty.getId()).isEqualTo(PETTY_ID);
	}

	@Test
	void editCopiesNameBirthDateAndTypeOntoOwnersPetWhenInstancesDiffer() throws Exception {
		given(this.owners.findById(OWNER_ID)).willAnswer(invocation -> {
			Owner fresh = new Owner();
			Pet freshPetty = new Pet();
			freshPetty.setId(PETTY_ID);
			freshPetty.setName("petty");
			freshPetty.setBirthDate(LocalDate.of(2010, 1, 1));
			fresh.addPet(freshPetty);
			return Optional.of(fresh);
		});
		ArgumentCaptor<Owner> saved = ArgumentCaptor.forClass(Owner.class);

		mockMvc
			.perform(post("/owners/{ownerId}/pets/{petId}/edit", OWNER_ID, PETTY_ID).param("name", "Betty")
				.param("type", "hamster")
				.param("birthDate", "2015-02-12"))
			.andExpect(status().is3xxRedirection());

		verify(owners).saveAndFlush(saved.capture());
		assertThat(saved.getValue().getPets()).hasSize(1);
		Pet savedPet = saved.getValue().getPet(PETTY_ID);
		assertThat(savedPet.getName()).isEqualTo("Betty");
		assertThat(savedPet.getBirthDate()).isEqualTo(LocalDate.of(2015, 2, 12));
		assertThat(savedPet.getType()).isSameAs(hamster);
	}

	@Test
	void editDoesNotRequireType() throws Exception {
		mockMvc
			.perform(post("/owners/{ownerId}/pets/{petId}/edit", OWNER_ID, PETTY_ID).param("name", "Betty")
				.param("birthDate", "2015-02-12"))
			.andExpect(status().is3xxRedirection());
	}

	@Test
	void editAcceptsBirthDateOfToday() throws Exception {
		mockMvc
			.perform(post("/owners/{ownerId}/pets/{petId}/edit", OWNER_ID, PETTY_ID).param("name", "Betty")
				.param("type", "hamster")
				.param("birthDate", LocalDate.now().toString()))
			.andExpect(status().is3xxRedirection());
	}

	@Test
	void editMissingBirthDateIsRequiredAndNotSaved() throws Exception {
		mockMvc
			.perform(post("/owners/{ownerId}/pets/{petId}/edit", OWNER_ID, PETTY_ID).param("name", "Betty")
				.param("type", "hamster")
				.param("birthDate", ""))
			.andExpect(status().isOk())
			.andExpect(view().name(FORM))
			.andExpect(model().errorCount(1))
			.andExpect(model().attributeHasFieldErrorCode("pet", "birthDate", "required"));
		verify(owners, never()).saveAndFlush(any());
	}

	@Test
	void editDuplicateNameOfOtherPetIsCaseInsensitive() throws Exception {
		mockMvc
			.perform(post("/owners/{ownerId}/pets/{petId}/edit", OWNER_ID, DOGGY_ID).param("name", "PETTY")
				.param("type", "hamster")
				.param("birthDate", "2015-02-12"))
			.andExpect(status().isOk())
			.andExpect(model().errorCount(1))
			.andExpect(model().attributeHasFieldErrorCode("pet", "name", "duplicate"));
		verify(owners, never()).saveAndFlush(any());
	}

	@Test
	void editOwnNameInDifferentCaseIsAllowed() throws Exception {
		mockMvc
			.perform(post("/owners/{ownerId}/pets/{petId}/edit", OWNER_ID, PETTY_ID).param("name", "PETTY")
				.param("birthDate", "2015-02-12"))
			.andExpect(status().is3xxRedirection());
		assertThat(petty.getName()).isEqualTo("PETTY");
	}

	@Test
	void editNameOf31CharsRejectedWithSize() throws Exception {
		mockMvc
			.perform(post("/owners/{ownerId}/pets/{petId}/edit", OWNER_ID, PETTY_ID).param("name", "A".repeat(31))
				.param("birthDate", "2015-02-12"))
			.andExpect(status().isOk())
			.andExpect(model().errorCount(1))
			.andExpect(model().attributeHasFieldErrorCode("pet", "name", "size"));
	}

	@Test
	void editBlankNameReportsOnlyRequiredNotDuplicate() throws Exception {
		mockMvc
			.perform(post("/owners/{ownerId}/pets/{petId}/edit", OWNER_ID, PETTY_ID).param("name", "")
				.param("birthDate", "2015-02-12"))
			.andExpect(model().errorCount(1))
			.andExpect(model().attributeHasFieldErrorCode("pet", "name", "required"));
	}

	@Test
	void editRejectedFormHasAlreadyBoundValuesOntoOwnersPet() throws Exception {
		mockMvc
			.perform(post("/owners/{ownerId}/pets/{petId}/edit", OWNER_ID, DOGGY_ID).param("name", "petty")
				.param("birthDate", "2015-02-12"))
			.andExpect(status().isOk());
		// SUSPECT: binding writes straight onto the owner's loaded pet, so after a
		// rejected edit the in-memory owner holds two pets named "petty". Nothing is
		// saved.
		assertThat(owner.getPet(DOGGY_ID).getName()).isEqualTo("petty");
		verify(owners, never()).saveAndFlush(any());
	}

	@Test
	void editIgnoresSubmittedId() throws Exception {
		mockMvc
			.perform(post("/owners/{ownerId}/pets/{petId}/edit", OWNER_ID, PETTY_ID).param("id", "99")
				.param("name", "Betty")
				.param("birthDate", "2015-02-12"))
			.andExpect(status().is3xxRedirection());
		assertThat(petty.getId()).isEqualTo(PETTY_ID);
	}

	@Test
	void editUnknownPetIdFailsWithNullPointerAndDoesNotSave() {
		// SUSPECT: findPet returns null for an unknown pet, validation is skipped and
		// isNameTakenByAnotherPet dereferences the null pet. The add-pet branch of
		// updatePetDetails is never reached from this endpoint.
		assertThatThrownBy(
				() -> mockMvc.perform(post("/owners/{ownerId}/pets/{petId}/edit", OWNER_ID, 99).param("name", "Betty")
					.param("type", "hamster")
					.param("birthDate", "2015-02-12")))
			.hasRootCauseInstanceOf(NullPointerException.class);
		verify(owners, never()).saveAndFlush(any());
	}

	@Test
	void editUniqueViolationMessageMatchedCaseInsensitively() throws Exception {
		given(owners.saveAndFlush(any(Owner.class)))
			.willThrow(new DataIntegrityViolationException("Duplicate key: UNIQUE_OWNER_PET_NAME"));
		mockMvc
			.perform(post("/owners/{ownerId}/pets/{petId}/edit", OWNER_ID, PETTY_ID).param("name", "Betty")
				.param("birthDate", "2015-02-12"))
			.andExpect(status().isOk())
			.andExpect(view().name(FORM))
			.andExpect(model().attributeHasFieldErrorCode("pet", "name", "duplicate"));
	}

	@Test
	void editOtherIntegrityViolationIsRethrown() {
		given(owners.saveAndFlush(any(Owner.class))).willThrow(new DataIntegrityViolationException("fk_type"));
		assertThatThrownBy(() -> mockMvc
			.perform(post("/owners/{ownerId}/pets/{petId}/edit", OWNER_ID, PETTY_ID).param("name", "Betty")
				.param("birthDate", "2015-02-12")))
			.hasRootCauseInstanceOf(DataIntegrityViolationException.class);
	}

}
